from dataclasses import dataclass
from decimal import Decimal
from html import escape


@dataclass
class Product:
    name: str
    price: Decimal
    in_stock: bool
    is_active: bool = True


class QuerySet(list):
    def filter(self, **kw):
        return QuerySet(p for p in self if all(getattr(p, k) == v for k, v in kw.items()))

    def order_by(self, field):
        return QuerySet(sorted(self, key=lambda p: getattr(p, field)))


class Manager:
    def __init__(self, items):
        self.items = QuerySet(items)

    def filter(self, **kw):
        return self.items.filter(**kw)


Product.objects = Manager([
    Product("Wireless Mouse", Decimal("24.99"), True),
    Product("Mechanical Keyboard", Decimal("89.50"), False),
    Product("USB-C Hub", Decimal("39.00"), True),
    Product("Old Monitor", Decimal("59.00"), True, is_active=False),
])

BASE = """<!DOCTYPE html>
<html>
<head><title>Shop</title></head>
<body>
{content}
</body>
</html>"""


def render(request, template_name, context):
    parts = ["  <h1>Products</h1>"]
    for product in context["products"]:
        badge = ('<span class="badge-green">In Stock</span>' if product.in_stock
                 else '<span class="badge-red">Out of Stock</span>')
        parts.append(
            '  <div class="product">\n'
            f"    <h3>{escape(product.name)}</h3>\n"
            f"    <p>${product.price}</p>\n"
            f"    {badge}\n"
            "  </div>"
        )
    if not context["products"]:
        parts.append("  <p>No products available.</p>")
    return BASE.format(content="\n".join(parts))


def product_list(request):
    products = Product.objects.filter(is_active=True).order_by('name')
    return render(request, 'shop/product_list.html', {'products': products})


if __name__ == "__main__":
    page = product_list(None)
    assert "Old Monitor" not in page
    assert page.count('class="product"') == 3
    assert "In Stock" in page and "Out of Stock" in page
    print("A rendered HTML page listing all active products with stock status")
